Method.Implementation:
	 Set tSC= $$$OK
	 $$$TRACE(" Inside InvokePostService ")

	  try {
	 set httpBodyData = pInput.Read(.len,.status)
	 $$$TRACE(" httpBody : "_httpBodyData)	 

	 set httpBodyParamsList = $LISTFROMSTRING(httpBodyData, "&")
	 // name_first=MERGE1&name_middle=&name_last=XTEST&keep_mrn=789109&delete_mrn=123456	 
	 Set n = $ListLength(httpBodyParamsList)
	 Set firstName=""
	 Set midName=""
	 Set lastName=""
	 Set keepMrn=""
	 Set deleteMrn=""
     For i=1:1:n {
	     $$$TRACE("httpBodyParamsList("_i_")::"_$List(httpBodyParamsList,i))
	     Set piece = $LISTFROMSTRING($List(httpBodyParamsList,i),"=")
	     if ($LIST(piece,1)="name_first"){
		     Set firstName=$LIST(piece,2)
		     $$$TRACE("First Name : "_firstName)
	     }
	     if ($LIST(piece,1)="name_middle"){
		     Set midName=$LIST(piece,2)
		     $$$TRACE("Mid Name : "_midName)
	     }
	     if ($LIST(piece,1)="name_last"){
		     Set lastName=$LIST(piece,2)
		     $$$TRACE("Last Name : "_lastName)
	     }
	     if ($LIST(piece,1)="keep_mrn"){
		     Set keepMrn=$LIST(piece,2)
		     $$$TRACE("Keep Mrn : "_keepMrn)
	     }
	     if ($LIST(piece,1)="delete_mrn"){
		     Set deleteMrn=$LIST(piece,2)
		     $$$TRACE("Delete Mrn : "_deleteMrn)
	     }	   	   
     }

	 Set pResponse=##class(IHC.ITF.Response.mPageMergeDataResponse).%New()
	 Set pResponse.delMrn = deleteMrn
	 Set pResponse.keepMrn = keepMrn
	 Set pResponse.lastName = lastName
	 Set pResponse.firstName = firstName
	 Set pResponse.midName = midName

	 do ..SendRequestAsync(..TargetConfigNames,pResponse)	

 }catch e
	{
		 $$$TRACE(" Unknown Exception: " _ e)
		 set errTxt = $System.Status.GetErrorText("Unknown Exception while receiving post request from mPage. "_e)		 
		 Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName,errTxt)	  
		 set tSC = $$$OK

	}
		  quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
